package com.eduflow.service;
import com.eduflow.dto.AcademicDtos.*; import com.eduflow.entity.*; import com.eduflow.exception.EduFlowException;
import com.eduflow.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.util.*; import java.math.BigDecimal;
@Service @RequiredArgsConstructor
public class AcademicService {
 private final CenterRepository centers; private final TeacherRepository teachers; private final CourseRepository courses; private final StudyGroupRepository groups; private final LessonRepository lessons; private final StudentRepository students; private final AttendanceRepository attendance; private final GradeRepository grades;
 private Center center(Long id){if(id==null)throw fail(HttpStatus.BAD_REQUEST,"tenant.context.required"); Center c=centers.findById(id).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"center.not-found")); if(c.getStatus()!=CenterStatus.ACTIVE)throw fail(HttpStatus.FORBIDDEN,"tenant.center.inactive"); return c;}
 private EduFlowException fail(HttpStatus s,String code){return new EduFlowException(s,code);}
 private String clean(String s){return s==null||s.isBlank()?null:s.trim();}
 @Transactional(readOnly=true) public List<Teacher> teachers(Long c){center(c);return teachers.findAllByCenter_IdAndStatusOrderByLastNameAscFirstNameAsc(c,"ACTIVE");}
 @Transactional public Teacher addTeacher(Long c,TeacherRequest r){Center x=center(c);String code=r.teacherCode().trim();if(teachers.existsByCenter_IdAndTeacherCode(c,code))throw fail(HttpStatus.CONFLICT,"teacher.code.exists");return teachers.save(new Teacher(x,code,r.firstName().trim(),r.lastName().trim(),clean(r.email()),clean(r.phone()),clean(r.specialization())));}
 @Transactional(readOnly=true) public List<Course> courses(Long c){center(c);return courses.findAllByCenter_IdAndActiveTrueOrderByNameAsc(c);}
 @Transactional public Course addCourse(Long c,CourseRequest r){Center x=center(c);String code=r.courseCode().trim();if(courses.existsByCenter_IdAndCourseCode(c,code))throw fail(HttpStatus.CONFLICT,"course.code.exists");return courses.save(new Course(x,code,r.name().trim(),clean(r.description())));}
 @Transactional(readOnly=true) public List<StudyGroup> groups(Long c){center(c);return groups.findAllByCenter_IdAndActiveTrueOrderByNameAsc(c);}
 @Transactional public StudyGroup addGroup(Long c,GroupRequest r){Center x=center(c);if(r.endsOn()!=null&&r.startsOn()!=null&&r.endsOn().isBefore(r.startsOn()))throw fail(HttpStatus.BAD_REQUEST,"group.date.invalid");String code=r.groupCode().trim();if(groups.existsByCenter_IdAndGroupCode(c,code))throw fail(HttpStatus.CONFLICT,"group.code.exists");Course course=courses.findByIdAndCenter_IdAndActiveTrue(r.courseId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"course.not-found"));Teacher teacher=teachers.findByIdAndCenter_Id(r.teacherId(),c).filter(t->"ACTIVE".equals(t.getStatus())).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"teacher.not-found"));return groups.save(new StudyGroup(x,course,teacher,code,r.name().trim(),r.startsOn(),r.endsOn()));}
 @Transactional(readOnly=true) public List<Lesson> lessons(Long c,Long g){center(c);groups.findByIdAndCenter_IdAndActiveTrue(g,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));return lessons.findAllByCenter_IdAndGroup_IdOrderByStartsAtAsc(c,g);}
 @Transactional public Lesson addLesson(Long c,LessonRequest r){Center x=center(c);if(!r.endsAt().isAfter(r.startsAt()))throw fail(HttpStatus.BAD_REQUEST,"lesson.time.invalid");StudyGroup g=groups.findByIdAndCenter_IdAndActiveTrue(r.groupId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));return lessons.save(new Lesson(x,g,r.title().trim(),clean(r.description()),r.startsAt(),r.endsAt()));}
 @Transactional public AttendanceRecord markAttendance(Long c,AttendanceRequest r){Center x=center(c);String status=r.status().trim().toUpperCase(Locale.ROOT);if(!Set.of("PRESENT","ABSENT","LATE","EXCUSED").contains(status))throw fail(HttpStatus.BAD_REQUEST,"attendance.status.invalid");Lesson l=lessons.findByIdAndCenter_Id(r.lessonId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"lesson.not-found"));Student s=students.findByIdAndCenter_Id(r.studentId(),c).filter(v->v.getStatus()==StudentStatus.ACTIVE).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"student.not-found"));return attendance.save(new AttendanceRecord(x,l,s,status,clean(r.note())));}
 @Transactional(readOnly=true) public List<AttendanceRecord> attendance(Long c,Long lesson){center(c);lessons.findByIdAndCenter_Id(lesson,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"lesson.not-found"));return attendance.findAllByCenter_IdAndLesson_IdOrderByStudent_LastNameAsc(c,lesson);}
 @Transactional public GradeRecord addGrade(Long c,GradeRequest r){Center x=center(c);if(r.score().compareTo(r.maxScore())>0)throw fail(HttpStatus.BAD_REQUEST,"grade.score.invalid");Student s=students.findByIdAndCenter_Id(r.studentId(),c).filter(v->v.getStatus()==StudentStatus.ACTIVE).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"student.not-found"));StudyGroup g=groups.findByIdAndCenter_IdAndActiveTrue(r.groupId(),c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"group.not-found"));return grades.save(new GradeRecord(x,s,g,r.title().trim(),r.score(),r.maxScore(),clean(r.comment())));}
 @Transactional(readOnly=true) public List<GradeRecord> grades(Long c,Long student){center(c);students.findByIdAndCenter_Id(student,c).orElseThrow(()->fail(HttpStatus.NOT_FOUND,"student.not-found"));return grades.findAllByCenter_IdAndStudent_IdOrderByCreatedAtDesc(c,student);}
}
